 @Schema(name="SubscriptionFakeRequest") public record SubscriptionFakeRequest(dev.genericpayments.platform.subscriptions.application.port.in.ControlFakeSubscriptionUseCase.Action action,dev.genericpayments.platform.subscriptions.application.port.out.FakeSubscriptionControlPort.Scenario scenario,Instant until){}
