 @Schema(name="SubscriptionAccessResponse") public record SubscriptionAccessResponse(@JsonProperty("allowed") boolean allowed,@JsonProperty("reason") AccessDecision.Reason reason,@JsonProperty("site_id") UUID siteId,@JsonProperty("customer_id") UUID customerId,@JsonProperty("product_id") UUID productId,@JsonProperty("subscription_id") UUID subscriptionId,@JsonProperty("entitled_price_id") UUID entitledPriceId,@JsonProperty("entitled_price_version") Integer entitledPriceVersion,@JsonProperty("revision") long revision,@JsonProperty("evaluated_at") Instant evaluatedAt,@JsonProperty("valid_until") Instant validUntil) {}
 @Schema(name="SubscriptionResponse") public record SubscriptionResponse(@JsonProperty("subscription_id") UUID subscriptionId,@JsonProperty("site_id") UUID siteId,@JsonProperty("customer_id") UUID customerId,@JsonProperty("product_id") UUID productId,@JsonProperty("payment_account_id") UUID paymentAccountId,@JsonProperty("billing_price") SubscriptionPriceResponse billingPrice,@JsonProperty("entitled_price") SubscriptionPriceResponse entitledPrice,@JsonProperty("state") String state,@JsonProperty("billing_status") Subscription.Status billingStatus,@JsonProperty("revision") long revision,@JsonProperty("period") SubscriptionPeriodResponse period,@JsonProperty("paid_through") Instant paidThrough,@JsonProperty("trial") SubscriptionPeriodResponse trial,@JsonProperty("cancellation") SubscriptionCancellationResponse cancellation,@JsonProperty("pending_change") SubscriptionPendingChangeResponse pendingChange,@JsonProperty("pending_operation") SubscriptionPendingOperationResponse pendingOperation,@JsonProperty("debt") SubscriptionDebtResponse debt,@JsonProperty("access") SubscriptionAccessResponse access,@JsonProperty("permitted_actions") Set<SubscriptionView.PermittedAction> permittedActions,@JsonProperty("next_amount") SubscriptionNextAmountResponse nextAmount,@JsonProperty("created_at") Instant createdAt,@JsonProperty("updated_at") Instant updatedAt) {}
 @Schema(name="SubscriptionOperationResponse") public record SubscriptionOperationResponse(@JsonProperty("operation_id") UUID operationId,@JsonProperty("subscription_id") UUID subscriptionId,@JsonProperty("status") SubscriptionOperation.Status status,@JsonProperty("action_available") boolean actionAvailable) {}
 @Schema(name="SubscriptionMutationResponse") public record SubscriptionMutationResponse(@JsonProperty("operation_id") UUID operationId,@JsonProperty("subscription_id") UUID subscriptionId,@JsonProperty("status") SubscriptionOperation.Status status,@JsonProperty("action_available") boolean actionAvailable,@JsonProperty("next_action") SubscriptionActionResponse nextAction) {@Override public String toString(){return "SubscriptionMutationResponse[redacted]";}}
 @Schema(name="SubscriptionActionResponse") public record SubscriptionActionResponse(@JsonProperty("kind") SubscriptionProviderModels.ActionKind kind,@JsonProperty("secret") String secret,@JsonProperty("expires_at") Instant expiresAt) {@Override public String toString(){return "SubscriptionActionResponse[redacted]";}}
 @Schema(name="SubscriptionPortalResponse") public record SubscriptionPortalResponse(@JsonProperty("navigation_url") String navigationUrl,@JsonProperty("expires_at") Instant expiresAt,@JsonProperty("simulated") boolean simulated) {@Override public String toString(){return "SubscriptionPortalResponse[redacted]";}}
 @Schema(name="SubscriptionBillingResponse") public record SubscriptionBillingResponse(@JsonProperty("billing_record_id") UUID billingRecordId,@JsonProperty("subscription_id") UUID subscriptionId,@JsonProperty("kind") BillingRecord.Kind kind,@JsonProperty("price") SubscriptionPriceResponse price,@JsonProperty("previous_price") SubscriptionPriceResponse previousPrice,@JsonProperty("period") SubscriptionPeriodResponse period,@JsonProperty("amount_due_minor") long amountDueMinor,@JsonProperty("currency") String currency,@JsonProperty("settlement") BillingRecord.Settlement settlement,@JsonProperty("payment_ids") List<UUID> paymentIds,@JsonProperty("created_at") Instant createdAt,@JsonProperty("updated_at") Instant updatedAt) {}
 @Schema(name="SubscriptionQuoteResponse") public record SubscriptionQuoteResponse(@JsonProperty("quote_id") UUID quoteId,@JsonProperty("subscription_id") UUID subscriptionId,@JsonProperty("from_price_id") UUID fromPriceId,@JsonProperty("from_price_version") int fromPriceVersion,@JsonProperty("target_price") SubscriptionPriceResponse targetPrice,@JsonProperty("timing") ChangeTiming timing,@JsonProperty("due_now_minor") long dueNowMinor,@JsonProperty("next_amount_minor") long nextAmountMinor,@JsonProperty("currency") String currency,@JsonProperty("effective_at") Instant effectiveAt,@JsonProperty("expires_at") Instant expiresAt,@JsonProperty("tax_final") boolean taxFinal,@JsonProperty("subscription_revision") long subscriptionRevision,@JsonProperty("policy_version") long policyVersion) {}
 @Schema(name="SubscriptionEventResponse") public record SubscriptionEventResponse(@JsonProperty("event_id") UUID eventId,@JsonProperty("subscription_id") UUID subscriptionId,@JsonProperty("sequence") long sequence,@JsonProperty("revision") long revision,@JsonProperty("type") SubscriptionEvent.Type type,@JsonProperty("source") SubscriptionEvent.Source source,@JsonProperty("occurred_at") Instant occurredAt,@JsonProperty("received_at") Instant receivedAt,@JsonProperty("operation_id") UUID operationId,@JsonProperty("billing_record_id") UUID billingRecordId,@JsonProperty("payment_id") UUID paymentId) {}
 @Schema(name="SubscriptionOfferResponse") public record SubscriptionOfferResponse(@JsonProperty("price") SubscriptionPriceResponse price,@JsonProperty("direction") PlanTransition.Direction direction,@JsonProperty("allowed_timings") Set<ChangeTiming> allowedTimings,@JsonProperty("trial_eligible") boolean trialEligible) {}
 @Schema(name="SubscriptionPage") public record SubscriptionPage(@JsonProperty("items") List<SubscriptionResponse> items,@JsonProperty("next_cursor") String nextCursor) {}
