 @Schema(name="SubscriptionEventPage") public record SubscriptionEventPage(@JsonProperty("items") List<SubscriptionEventResponse> items,@JsonProperty("next_cursor") String nextCursor) {}
 @Schema(name="SubscriptionOffers") public record SubscriptionOffers(@JsonProperty("items") List<SubscriptionOfferResponse> items) {}
 @Schema(name="SubscriptionPolicyResponse") public record SubscriptionPolicyResponse(@JsonProperty("site_id") UUID siteId,@JsonProperty("version") long version,@JsonProperty("enabled") boolean enabled,@JsonProperty("grace_days") int graceDays,@JsonProperty("allow_immediate_cancellation") boolean allowImmediateCancellation,@JsonProperty("portal_enabled") boolean portalEnabled,@JsonProperty("defer_upgrades") boolean deferUpgrades,@JsonProperty("portal_return_urls") Set<String> portalReturnUrls) {}
 @Schema(name="SubscriptionTransitionResponse") public record SubscriptionTransitionResponse(@JsonProperty("site_id") UUID siteId,@JsonProperty("product_id") UUID productId,@JsonProperty("from_price_id") UUID fromPriceId,@JsonProperty("to_price_id") UUID toPriceId,@JsonProperty("direction") PlanTransition.Direction direction,@JsonProperty("immediate_allowed") boolean immediateAllowed,@JsonProperty("policy_version") long policyVersion) {}
 @Schema(name="SubscriptionTransitions") public record SubscriptionTransitions(@JsonProperty("items") List<SubscriptionTransitionResponse> items) {}
 @Schema(name="SubscriptionCreateRequest") public record SubscriptionCreateRequest(@JsonProperty("site_id") UUID siteId,@JsonProperty("customer_id") UUID customerId,@JsonProperty("price_id") UUID priceId,@JsonProperty("recurring_consent") @Schema(accessMode=Schema.AccessMode.WRITE_ONLY) Boolean recurringConsent) {@Override public String toString(){return "SubscriptionCreateRequest[redacted]";}}
 @Schema(name="SubscriptionPreviewRequest") public record SubscriptionPreviewRequest(@JsonProperty("target_price_id") UUID targetPriceId,@JsonProperty("timing") ChangeTiming timing) {@Override public String toString(){return "SubscriptionPreviewRequest[redacted]";}}
 @Schema(name="SubscriptionChangeRequest") public record SubscriptionChangeRequest(@JsonProperty("quote_id") UUID quoteId) {@Override public String toString(){return "SubscriptionChangeRequest[redacted]";}}
 @Schema(name="SubscriptionCancelRequest") public record SubscriptionCancelRequest(@JsonProperty("mode") CancelSubscriptionUseCase.Mode mode,@JsonProperty("confirmation") UUID confirmation) {@Override public String toString(){return "SubscriptionCancelRequest[redacted]";}}
 @Schema(name="SubscriptionConsentRequest") public record SubscriptionConsentRequest(@JsonProperty("recurring_consent") @Schema(accessMode=Schema.AccessMode.WRITE_ONLY) Boolean recurringConsent) {@Override public String toString(){return "SubscriptionConsentRequest[redacted]";}}
 @Schema(name="SubscriptionActionRequest") public record SubscriptionActionRequest(@JsonProperty("action_token") @Schema(accessMode=Schema.AccessMode.WRITE_ONLY) String actionToken) {@Override public String toString(){return "SubscriptionActionRequest[redacted]";}}
